svg.script:

(function() {
  // Estado da Aplicação
  var state = {
    mode: 1, // 1: Visão Geral, 2: Simulador
    cdValue: 12.0
  };

  // Elementos do DOM
  var tab1 = document.getElementById('a12p11h-tab-1');
  var tab2 = document.getElementById('a12p11h-tab-2');

  var btn10 = document.getElementById('a12p11h-preset-10');
  var btn11 = document.getElementById('a12p11h-preset-11');
  var btn12 = document.getElementById('a12p11h-preset-12');
  var btn13 = document.getElementById('a12p11h-preset-13');

  var calcCd = document.getElementById('a12p11h-calc-cd');
  var calcCo = document.getElementById('a12p11h-calc-co');
  var diagStatus = document.getElementById('a12p11h-diag-status');
  var diagDesc = document.getElementById('a12p11h-diag-desc');

  var lineObs = document.getElementById('a12p11h-line-obs-elem');
  var lineDiag = document.getElementById('a12p11h-line-diag-elem');

  // Função de Atualização do Cálculo
  function updateCalculation(val) {
    state.cdValue = val;
    var coVal = (val - 1.5).toFixed(1);

    // Atualiza textos
    if (calcCd) calcCd.textContent = val.toFixed(1).replace('.', ',') + ' cm';
    if (calcCo) calcCo.textContent = coVal.replace('.', ',') + ' cm';

    // Atualiza diagnósticos segundo a convenção de cores (Verde=Normal, Vermelho=Alterado)
    if (coVal >= 10.5) {
      if (diagStatus) {
        diagStatus.textContent = '✓ BACIA ADEQUADA (EUNOCÓCICA / NORMAL)';
        diagStatus.setAttribute('class', 'a12p11h-val-badge a12p11h-status-pass');
      }
      if (diagDesc) diagDesc.textContent = 'Vera Obstétrica ≥ 10,5 cm: Canal livre para parto vaginal.';
      if (calcCo) calcCo.setAttribute('fill', '#10b981');
    } else if (coVal >= 9.5) {
      if (diagStatus) {
        diagStatus.textContent = '⚠ BACIA LIMÍTROFE (ATENÇÃO CLINICA)';
        diagStatus.setAttribute('class', 'a12p11h-val-badge');
        diagStatus.setAttribute('fill', '#f59e0b');
      }
      if (diagDesc) diagDesc.textContent = 'Vera Obstétrica entre 9,5 e 10,4 cm: Monitorar prova de trabalho de parto.';
      if (calcCo) calcCo.setAttribute('fill', '#f59e0b');
    } else {
      if (diagStatus) {
        diagStatus.textContent = '✕ PELVE VICIADA / ESTREITAMENTO (ALERTA)';
        diagStatus.setAttribute('class', 'a12p11h-val-badge a12p11h-status-fail');
      }
      if (diagDesc) diagDesc.textContent = 'Vera Obstétrica < 9,5 cm: Alto risco de Desproporção Cefalopélvica (DCP).';
      if (calcCo) calcCo.setAttribute('fill', '#ef4444');
    }

    // Destaque dos Botões de Preset
    [btn10, btn11, btn12, btn13].forEach(function(btn) {
      if (btn) btn.classList.remove('a12p11h-active');
    });
    if (val === 10.0 && btn10) btn10.classList.add('a12p11h-active');
    if (val === 11.5 && btn11) btn11.classList.add('a12p11h-active');
    if (val === 12.0 && btn12) btn12.classList.add('a12p11h-active');
    if (val === 13.0 && btn13) btn13.classList.add('a12p11h-active');
  }

  // Event Listeners dos Presets
  if (btn10) btn10.addEventListener('click', function() { updateCalculation(10.0); });
  if (btn11) btn11.addEventListener('click', function() { updateCalculation(11.5); });
  if (btn12) btn12.addEventListener('click', function() { updateCalculation(12.0); });
  if (btn13) btn13.addEventListener('click', function() { updateCalculation(13.0); });

  // Suporte a Teclado nos Botões
  [btn10, btn11, btn12, btn13, tab1, tab2].forEach(function(elem) {
    if (elem) {
      elem.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          elem.click();
        }
      });
    }
  });

  // Alternância de Abas
  if (tab1) {
    tab1.addEventListener('click', function() {
      tab1.classList.add('a12p11h-active');
      if (tab2) tab2.classList.remove('a12p11h-active');
      if (lineObs) lineObs.style.strokeWidth = '4px';
    });
  }
  if (tab2) {
    tab2.addEventListener('click', function() {
      tab2.classList.add('a12p11h-active');
      if (tab1) tab1.classList.remove('a12p11h-active');
      if (lineObs) lineObs.style.strokeWidth = '6px';
    });
  }

  // Inicialização
  updateCalculation(12.0);
})();
